from __future__ import annotations

import itertools
import time
from typing import Any

from .models import *  # noqa: F401,F403
from .models import JarvisEvent

_counter = itertools.count(1)


def parse_event(raw: Any) -> Any:
    """Validate a dict or JSON string against the event contract; returns the concrete *Event model."""
    if isinstance(raw, (str, bytes)):
        return JarvisEvent.model_validate_json(raw).root
    return JarvisEvent.model_validate(raw).root


# Opaque payload fields whose content is passed through untouched.
_OPAQUE_KEYS = {"data", "args"}


def _prune_none(obj: Any) -> Any:
    """Drop None-valued keys: Zod .optional() on the TS side rejects null."""
    if isinstance(obj, dict):
        return {k: (v if k in _OPAQUE_KEYS else _prune_none(v)) for k, v in obj.items() if v is not None or k in _OPAQUE_KEYS}
    return obj


def make_event(type: str, payload: dict[str, Any], session_id: str = "demo") -> dict[str, Any]:
    """Build a validated event dict ready to POST to the orchestrator or send over WS."""
    event = {
        "id": f"{int(time.time() * 1000):x}-{next(_counter)}",
        "ts": int(time.time() * 1000),
        "sessionId": session_id,
        "type": type,
        "payload": _prune_none(payload),
    }
    parse_event(event)
    return event
